"use client";

import React, { useEffect, useMemo, useRef, useState } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { useGSAP } from "@gsap/react";
import { AnimatePresence, motion } from "framer-motion";
import { ArrowUpRight, Check, Copy, Flower2, Mail, Moon, Sparkles, Sun } from "lucide-react";
import { PORTFOLIO, SkillCategory } from "@/data/portfolio";

gsap.registerPlugin(useGSAP, ScrollTrigger);

const CATEGORIES: (SkillCategory | "All")[] = [
  "All",
  "Languages",
  "Frontend",
  "Systems & CS",
  "Workflow",
];

const CHAPTER_META: Record<SkillCategory, { numeral: string; heading: string }> = {
  Languages: { numeral: "I.", heading: "Languages" },
  Frontend: { numeral: "II.", heading: "Frontend & Motion" },
  "Systems & CS": { numeral: "III.", heading: "Systems & CS" },
  Workflow: { numeral: "IV.", heading: "Workflow & Hosting" },
};

export default function AtelierPortfolio() {
  const rootRef = useRef<HTMLDivElement>(null);
  const [mode, setMode] = useState<"silk" | "velvet">("silk");
  const [activeCategory, setActiveCategory] = useState<SkillCategory | "All">("All");
  const [selectedSkillId, setSelectedSkillId] = useState<string>("java");
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    if (mode === "velvet") {
      document.documentElement.setAttribute("data-theme", "velvet");
    } else {
      document.documentElement.removeAttribute("data-theme");
    }
  }, [mode]);

  useGSAP(
    () => {
      gsap.from(".atelier-hero", {
        y: 22,
        opacity: 0,
        duration: 0.85,
        stagger: 0.1,
        ease: "power3.out",
        clearProps: "transform",
      });

      gsap.utils.toArray<HTMLElement>(".atelier-section").forEach((el) => {
        gsap.from(el, {
          y: 24,
          opacity: 0,
          duration: 0.75,
          ease: "power2.out",
          clearProps: "transform",
          scrollTrigger: {
            trigger: el,
            start: "top 86%",
            once: true,
          },
        });
      });
    },
    { scope: rootRef }
  );

  const groupedSkills = useMemo(() => {
    const cats: SkillCategory[] = ["Languages", "Frontend", "Systems & CS", "Workflow"];
    return cats.map((cat) => ({
      category: cat,
      ...CHAPTER_META[cat],
      items: PORTFOLIO.skills.filter((s) => s.category === cat),
    }));
  }, []);

  const filteredSkills = useMemo(() => {
    if (activeCategory === "All") return PORTFOLIO.skills;
    return PORTFOLIO.skills.filter((s) => s.category === activeCategory);
  }, [activeCategory]);

  const handleCopyEmail = async () => {
    try {
      await navigator.clipboard.writeText(PORTFOLIO.email);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1800);
    } catch {
      // Ignore clipboard unavailability
    }
  };

  return (
    <div ref={rootRef} className="relative min-h-screen overflow-hidden">
      {/* Gentle watercolor silk backdrop */}
      <div aria-hidden className="pointer-events-none fixed inset-0 -z-10">
        <div
          className="absolute -left-24 -top-24 h-[520px] w-[520px] rounded-full blur-[120px] opacity-65 transition-colors duration-500"
          style={{ background: "var(--bg-wash-a)" }}
        />
        <div
          className="absolute -bottom-32 -right-24 h-[520px] w-[520px] rounded-full blur-[130px] opacity-65 transition-colors duration-500"
          style={{ background: "var(--bg-wash-b)" }}
        />
      </div>

      {/* HEADER */}
      <header className="sticky top-0 z-40 border-b border-[var(--border)] bg-[var(--bg)]/85 backdrop-blur-md">
        <div className="mx-auto flex max-w-6xl items-center justify-between px-5 py-4 sm:px-8">
          <a href="#top" className="flex items-center gap-2.5 group">
            <span className="flex h-8 w-8 items-center justify-center rounded-full border border-[var(--border)] bg-[var(--surface)] font-editorial italic text-sm font-semibold text-[var(--rose)] transition-transform group-hover:scale-105">
              {PORTFOLIO.initials}
            </span>
            <span className="font-editorial text-xl font-medium tracking-tight text-[var(--ink)]">
              {PORTFOLIO.name}
            </span>
          </a>

          <nav className="hidden items-center gap-7 text-xs font-medium tracking-wide text-[var(--ink-muted)] md:flex">
            <a href="#craft" className="hover:text-[var(--rose)] transition-colors">
              Craft
            </a>
            <a href="#work" className="hover:text-[var(--rose)] transition-colors">
              Selected Work
            </a>
            <a href="#notes" className="hover:text-[var(--rose)] transition-colors">
              Philosophy
            </a>
            <a href="#contact" className="hover:text-[var(--rose)] transition-colors">
              Contact
            </a>
          </nav>

          <div className="flex items-center gap-2.5">
            <button
              onClick={() => setMode((m) => (m === "silk" ? "velvet" : "silk"))}
              className="inline-flex items-center gap-1.5 rounded-full border border-[var(--border)] bg-[var(--surface)] px-3.5 py-1.5 text-xs font-medium text-[var(--ink-muted)] hover:border-[var(--border-hover)] hover:text-[var(--ink)] transition-colors cursor-pointer"
              aria-label="Switch Silk or Velvet palette"
            >
              {mode === "silk" ? (
                <Moon className="h-3.5 w-3.5 text-[var(--rose)]" />
              ) : (
                <Sun className="h-3.5 w-3.5 text-[var(--rose)]" />
              )}
              {mode === "silk" ? "Velvet" : "Silk"}
            </button>

            <a
              href={PORTFOLIO.github}
              target="_blank"
              rel="noreferrer"
              className="inline-flex items-center gap-1 rounded-full bg-[var(--rose)] px-4 py-1.5 text-xs font-medium text-[var(--rose-ink)] hover:opacity-90 transition-opacity"
            >
              GitHub
              <ArrowUpRight className="h-3.5 w-3.5" />
            </a>
          </div>
        </div>
      </header>

      <main id="top" className="mx-auto max-w-6xl px-5 sm:px-8">
        {/* HERO SECTION */}
        <section className="grid grid-cols-1 items-center gap-12 pb-20 pt-12 lg:grid-cols-12 lg:pt-16">
          <div className="lg:col-span-7 space-y-6">
            <div className="atelier-hero inline-flex items-center gap-2 rounded-full border border-[var(--border)] bg-[var(--surface)] px-4 py-1.5 text-xs text-[var(--ink-muted)]">
              <Flower2 className="h-3.5 w-3.5 text-[var(--rose)]" />
              <span>{PORTFOLIO.greeting}</span>
            </div>

            <div className="atelier-hero">
              <h1 className="font-editorial text-5xl font-medium tracking-tight text-[var(--ink)] sm:text-7xl leading-[1.02]">
                {PORTFOLIO.firstName}{" "}
                <span className="italic font-normal text-[var(--rose)]">
                  {PORTFOLIO.lastName}
                </span>
              </h1>
              <p className="mt-3 text-base sm:text-lg font-medium text-[var(--ink-muted)]">
                {PORTFOLIO.headline}
              </p>
            </div>

            <p className="atelier-hero max-w-xl text-sm sm:text-base leading-relaxed text-[var(--ink-muted)]">
              {PORTFOLIO.bio}
            </p>

            <div className="atelier-hero flex flex-wrap items-center gap-3 pt-1">
              <motion.button
                whileTap={{ scale: 0.97 }}
                onClick={handleCopyEmail}
                className="inline-flex items-center gap-2 rounded-full bg-[var(--rose)] px-6 py-3 text-xs font-semibold tracking-wide text-[var(--rose-ink)] shadow-sm hover:opacity-95 transition-opacity cursor-pointer"
              >
                {copied ? <Check className="h-3.5 w-3.5" /> : <Copy className="h-3.5 w-3.5" />}
                {copied ? "Copied email!" : PORTFOLIO.email}
              </motion.button>

              <motion.a
                whileTap={{ scale: 0.97 }}
                href={PORTFOLIO.github}
                target="_blank"
                rel="noreferrer"
                className="inline-flex items-center gap-1.5 rounded-full border border-[var(--border)] bg-[var(--surface)] px-5 py-3 text-xs font-medium text-[var(--ink)] hover:border-[var(--border-hover)] transition-colors"
              >
                github.com/{PORTFOLIO.handle}
                <ArrowUpRight className="h-3.5 w-3.5 text-[var(--rose)]" />
              </motion.a>
            </div>

            {/* Delicate 3-column summary */}
            <div className="atelier-hero grid grid-cols-1 gap-3 pt-4 sm:grid-cols-3">
              {PORTFOLIO.highlights.map((item) => (
                <div
                  key={item.label}
                  className="rounded-2xl border border-[var(--border)] bg-[var(--surface)]/80 px-4 py-3.5"
                >
                  <div className="text-[11px] font-medium uppercase tracking-wider text-[var(--rose)]">
                    {item.label}
                  </div>
                  <div className="mt-1 text-xs font-medium text-[var(--ink)]">
                    {item.value}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Right: Editorial Silk & Crescent Botanical Arch (2D, zero 3D) */}
          <div className="atelier-hero lg:col-span-5">
            <motion.div
              whileHover={{ y: -4 }}
              transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}
              className="relative mx-auto flex h-[410px] max-w-sm flex-col items-center justify-between overflow-hidden rounded-t-[200px] rounded-b-[32px] silk-card bg-gradient-to-b from-[var(--surface)] via-[var(--surface)] to-[var(--surface-soft)] px-8 pb-8 pt-12 text-center"
            >
              {/* Delicate inner arch hairline */}
              <div
                aria-hidden
                className="pointer-events-none absolute inset-3.5 rounded-t-[185px] rounded-b-[22px] border border-[var(--border)]/80"
              />

              {/* Fine botanical crescent & star SVG motif */}
              <div className="relative z-10 flex flex-col items-center">
                <svg
                  viewBox="0 0 120 120"
                  className="h-24 w-24 text-[var(--rose)]"
                  fill="none"
                  xmlns="http://www.w3.org/2000/svg"
                  aria-hidden
                >
                  <circle
                    cx="60"
                    cy="60"
                    r="46"
                    stroke="currentColor"
                    strokeWidth="0.8"
                    strokeDasharray="2 4"
                    opacity="0.55"
                  />
                  <path
                    d="M68 30C52.5 32.5 41 45.8 41 61.5C41 78.9 55.1 93 72.5 93C78.8 93 84.7 91.1 89.6 87.9C76.2 88.2 65 77.3 65 63.8C65 51.5 74.1 41.3 86 39.6C80.8 33.7 74.7 30.8 68 30Z"
                    stroke="currentColor"
                    strokeWidth="1.25"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                  <path
                    d="M84 44L85.8 49.2L91 51L85.8 52.8L84 58L82.2 52.8L77 51L82.2 49.2L84 44Z"
                    fill="currentColor"
                    opacity="0.85"
                  />
                  <circle cx="48" cy="36" r="1.5" fill="currentColor" opacity="0.6" />
                </svg>

                <span className="mt-2 font-editorial italic text-4xl font-medium tracking-wide text-[var(--ink)]">
                  {PORTFOLIO.initials}
                </span>
              </div>

              <div className="relative z-10 space-y-2 px-2">
                <p className="font-editorial italic text-xl leading-snug text-[var(--ink)]">
                  &ldquo;Code with clarity, craft with grace.&rdquo;
                </p>
                <p className="text-xs tracking-wide text-[var(--ink-soft)]">
                  @{PORTFOLIO.handle} · {PORTFOLIO.location}
                </p>
              </div>

              <div className="relative z-10 inline-flex items-center gap-2 rounded-full border border-[var(--border)] bg-[var(--surface)] px-4 py-1.5 text-[11px] font-medium text-[var(--ink-muted)]">
                <span className="h-1.5 w-1.5 rounded-full bg-[var(--rose)]" />
                Open to thoughtful engineering roles
              </div>
            </motion.div>
          </div>
        </section>

        {/* CRAFT & SKILLS SECTION — REDESIGNED */}
        <section id="craft" className="atelier-section py-14">
          <div className="silk-card rounded-[32px] p-6 sm:p-10">
            {/* Clean header + single-line underline tabs */}
            <div className="flex flex-col gap-6 border-b border-[var(--border)] pb-6 lg:flex-row lg:items-end lg:justify-between">
              <div>
                <span className="font-editorial italic text-base text-[var(--rose)]">
                  01 · Craft &amp; Capabilities
                </span>
                <h2 className="mt-1 font-editorial text-3xl sm:text-4xl font-medium text-[var(--ink)]">
                  Languages, Frameworks &amp; Foundations
                </h2>
              </div>

              <div
                role="tablist"
                aria-label="Filter skills by category"
                className="flex items-center gap-5 overflow-x-auto border-b border-[var(--border)]/60 pb-1 lg:border-b-0 lg:pb-0"
              >
                {CATEGORIES.map((cat) => {
                  const isActive = activeCategory === cat;
                  return (
                    <button
                      key={cat}
                      role="tab"
                      aria-selected={isActive}
                      onClick={() => {
                        setActiveCategory(cat);
                        const first =
                          cat === "All"
                            ? PORTFOLIO.skills[0]
                            : PORTFOLIO.skills.find((s) => s.category === cat);
                        if (first) setSelectedSkillId(first.id);
                      }}
                      className={`relative whitespace-nowrap pb-2 text-xs sm:text-sm font-medium transition-colors cursor-pointer ${
                        isActive
                          ? "text-[var(--rose)]"
                          : "text-[var(--ink-muted)] hover:text-[var(--ink)]"
                      }`}
                    >
                      {cat}
                      {isActive && (
                        <motion.span
                          layoutId="craft-underline"
                          transition={{ type: "spring", stiffness: 380, damping: 32 }}
                          className="absolute bottom-0 left-0 right-0 h-[2px] rounded-full bg-[var(--rose)]"
                        />
                      )}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Body: 2x2 Atelier Chapters on "All", or Balanced 2-Column Editorial Ledger on specific category */}
            <AnimatePresence mode="wait">
              {activeCategory === "All" ? (
                <motion.div
                  key="all-chapters"
                  initial={{ opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -6 }}
                  transition={{ duration: 0.22 }}
                  className="mt-8 grid grid-cols-1 gap-5 md:grid-cols-2"
                >
                  {groupedSkills.map((group) => {
                    const selectedInGroup =
                      group.items.find((i) => i.id === selectedSkillId) || group.items[0];
                    return (
                      <div
                        key={group.category}
                        className="flex flex-col justify-between rounded-[24px] border border-[var(--border)] bg-[var(--bg)]/65 p-6 transition-colors hover:border-[var(--border-hover)]"
                      >
                        <div>
                          <div className="flex items-baseline justify-between border-b border-[var(--border)]/70 pb-3">
                            <h3 className="font-editorial text-2xl font-medium text-[var(--ink)]">
                              <span className="italic text-[var(--rose)] mr-2">
                                {group.numeral}
                              </span>
                              {group.heading}
                            </h3>
                            <button
                              onClick={() => setActiveCategory(group.category)}
                              className="text-[11px] font-medium text-[var(--ink-soft)] hover:text-[var(--rose)] transition-colors cursor-pointer"
                            >
                              Explore →
                            </button>
                          </div>

                          <div className="mt-4 flex flex-wrap gap-2">
                            {group.items.map((skill) => {
                              const isPicked = selectedInGroup?.id === skill.id;
                              return (
                                <motion.button
                                  key={skill.id}
                                  whileTap={{ scale: 0.96 }}
                                  onClick={() => setSelectedSkillId(skill.id)}
                                  className={`rounded-full border px-3.5 py-1.5 text-xs font-medium transition-all cursor-pointer ${
                                    isPicked
                                      ? "border-[var(--rose)] bg-[var(--rose)] text-[var(--rose-ink)] shadow-xs"
                                      : "border-[var(--border)] bg-[var(--surface)] text-[var(--ink)] hover:border-[var(--border-hover)] hover:bg-[var(--rose-soft)]/50"
                                  }`}
                                >
                                  {skill.name}
                                </motion.button>
                              );
                            })}
                          </div>
                        </div>

                        {selectedInGroup && (
                          <p className="mt-5 border-t border-[var(--border)]/60 pt-3 text-xs leading-relaxed text-[var(--ink-muted)]">
                            <span className="font-editorial italic text-sm font-medium text-[var(--rose)] mr-1.5">
                              {selectedInGroup.name}:
                            </span>
                            {selectedInGroup.note}
                          </p>
                        )}
                      </div>
                    );
                  })}
                </motion.div>
              ) : (
                <motion.div
                  key={activeCategory}
                  initial={{ opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -6 }}
                  transition={{ duration: 0.22 }}
                  className="mt-8 grid grid-cols-1 gap-4 md:grid-cols-2"
                >
                  {filteredSkills.map((skill, idx) => (
                    <motion.div
                      key={skill.id}
                      initial={{ opacity: 0, y: 6 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ duration: 0.2, delay: idx * 0.03 }}
                      className="group flex items-start gap-4 rounded-2xl border border-[var(--border)] bg-[var(--bg)]/60 p-5 transition-all hover:border-[var(--rose)]/60 hover:bg-[var(--rose-soft)]/35"
                    >
                      <span className="mt-1 font-editorial italic text-lg text-[var(--rose)] w-6 shrink-0">
                        0{idx + 1}
                      </span>
                      <div>
                        <h3 className="text-sm sm:text-base font-semibold text-[var(--ink)] group-hover:text-[var(--rose)] transition-colors">
                          {skill.name}
                        </h3>
                        <p className="mt-1 text-xs sm:text-sm leading-relaxed text-[var(--ink-muted)]">
                          {skill.note}
                        </p>
                      </div>
                    </motion.div>
                  ))}
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </section>

        {/* SELECTED WORK SECTION */}
        <section id="work" className="atelier-section py-12">
          <div className="mb-8 flex flex-col gap-2 sm:flex-row sm:items-end sm:justify-between">
            <div>
              <span className="font-editorial italic text-base text-[var(--rose)]">
                02 · Selected Work &amp; Chapters
              </span>
              <h2 className="mt-1 font-editorial text-3xl sm:text-4xl font-medium text-[var(--ink)]">
                Projects &amp; Upcoming Builds
              </h2>
            </div>
            <p className="text-xs text-[var(--ink-soft)]">
              Curated placeholders — customize anytime in{" "}
              <code className="rounded bg-[var(--surface-soft)] px-1.5 py-0.5 text-[var(--ink-muted)]">
                src/data/portfolio.ts
              </code>
            </p>
          </div>

          <div className="grid grid-cols-1 gap-6 md:grid-cols-3">
            {PORTFOLIO.projects.map((project) => (
              <motion.article
                key={project.number}
                whileHover={{ y: -4 }}
                transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
                className="silk-card flex flex-col justify-between rounded-[28px] p-7"
              >
                <div>
                  <div className="flex items-center justify-between">
                    <span className="font-editorial italic text-2xl text-[var(--rose)]">
                      {project.number}
                    </span>
                    <span className="rounded-full border border-[var(--border)] bg-[var(--surface-soft)] px-3 py-1 text-[11px] font-medium text-[var(--ink-muted)]">
                      {project.tag}
                    </span>
                  </div>

                  <h3 className="mt-5 font-editorial text-2xl font-medium text-[var(--ink)]">
                    {project.title}
                  </h3>
                  <p className="mt-2.5 text-sm leading-relaxed text-[var(--ink-muted)]">
                    {project.summary}
                  </p>
                </div>

                <div className="mt-6 flex items-center justify-between gap-2 border-t border-[var(--border)] pt-4">
                  <div className="flex flex-wrap gap-1.5">
                    {project.stack.map((tech) => (
                      <span
                        key={tech}
                        className="rounded-full bg-[var(--surface-soft)] px-2.5 py-1 text-[11px] font-medium text-[var(--ink-muted)]"
                      >
                        {tech}
                      </span>
                    ))}
                  </div>
                  {project.href && (
                    <a
                      href={project.href}
                      target="_blank"
                      rel="noreferrer"
                      className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full border border-[var(--border)] text-[var(--rose)] hover:bg-[var(--rose-soft)] transition-colors"
                      aria-label={`Open ${project.title}`}
                    >
                      <ArrowUpRight className="h-4 w-4" />
                    </a>
                  )}
                </div>
              </motion.article>
            ))}
          </div>
        </section>

        {/* PHILOSOPHY & CONTACT */}
        <section id="notes" className="atelier-section grid grid-cols-1 gap-6 py-12 lg:grid-cols-12">
          <div className="silk-card lg:col-span-7 rounded-[32px] p-7 sm:p-9">
            <span className="font-editorial italic text-base text-[var(--rose)]">
              03 · Engineering Philosophy
            </span>
            <h2 className="mt-1 font-editorial text-3xl font-medium text-[var(--ink)]">
              How I approach every build
            </h2>

            <div className="mt-6 divide-y divide-[var(--border)]">
              {PORTFOLIO.notes.map((note) => (
                <div key={note.numeral} className="flex gap-4 py-4 first:pt-0 last:pb-0">
                  <span className="font-editorial italic text-xl text-[var(--rose)] w-7 shrink-0">
                    {note.numeral}
                  </span>
                  <div>
                    <h3 className="text-sm font-semibold text-[var(--ink)]">{note.title}</h3>
                    <p className="mt-1 text-sm leading-relaxed text-[var(--ink-muted)]">
                      {note.detail}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div
            id="contact"
            className="silk-card lg:col-span-5 flex flex-col justify-between rounded-[32px] bg-gradient-to-br from-[var(--surface)] to-[var(--surface-soft)] p-7 sm:p-9"
          >
            <div>
              <span className="font-editorial italic text-base text-[var(--rose)]">
                04 · Say Hello
              </span>
              <h2 className="mt-1 font-editorial text-3xl font-medium text-[var(--ink)]">
                Let&apos;s connect
              </h2>
              <p className="mt-2.5 text-sm leading-relaxed text-[var(--ink-muted)]">
                Always happy to chat about software engineering roles, collaborations, or thoughtful
                products on the web.
              </p>
            </div>

            <div className="mt-6 space-y-3">
              <a
                href={`mailto:${PORTFOLIO.email}`}
                className="flex items-center justify-between rounded-2xl border border-[var(--border)] bg-[var(--surface)] px-4 py-3.5 text-xs sm:text-sm font-medium text-[var(--ink)] hover:border-[var(--border-hover)] transition-colors"
              >
                <span className="flex items-center gap-2.5">
                  <Mail className="h-4 w-4 text-[var(--rose)]" />
                  {PORTFOLIO.email}
                </span>
                <ArrowUpRight className="h-4 w-4 text-[var(--ink-soft)]" />
              </a>

              <a
                href={PORTFOLIO.github}
                target="_blank"
                rel="noreferrer"
                className="flex items-center justify-between rounded-2xl border border-[var(--border)] bg-[var(--surface)] px-4 py-3.5 text-xs sm:text-sm font-medium text-[var(--ink)] hover:border-[var(--border-hover)] transition-colors"
              >
                <span className="flex items-center gap-2.5">
                  <Sparkles className="h-4 w-4 text-[var(--rose)]" />
                  github.com/{PORTFOLIO.handle}
                </span>
                <ArrowUpRight className="h-4 w-4 text-[var(--ink-soft)]" />
              </a>

              <motion.button
                whileTap={{ scale: 0.98 }}
                onClick={handleCopyEmail}
                className="flex w-full items-center justify-center gap-2 rounded-full bg-[var(--rose)] px-5 py-3.5 text-xs font-semibold tracking-wide text-[var(--rose-ink)] hover:opacity-95 transition-opacity cursor-pointer"
              >
                {copied ? <Check className="h-3.5 w-3.5" /> : <Copy className="h-3.5 w-3.5" />}
                {copied ? "Copied to clipboard!" : "Copy Email Address"}
              </motion.button>
            </div>
          </div>
        </section>

        {/* FOOTER */}
        <footer className="mt-4 flex flex-col items-center justify-between gap-2 border-t border-[var(--border)] py-8 text-xs text-[var(--ink-soft)] sm:flex-row">
          <span className="font-editorial italic text-base text-[var(--ink-muted)]">
            {PORTFOLIO.name} · {new Date().getFullYear()}
          </span>
          <span>Crafted with Next.js, TypeScript, Tailwind CSS, GSAP &amp; Framer Motion</span>
        </footer>
      </main>
    </div>
  );
}
